window.docContents[55].resolve({"/Basic-Types/Maps-and-Sets/#Lean-__________________--Basic-Types--Maps-and-Sets--Library-Design":{"contents":"映射与集合上的所有基本操作都经过了完整验证。\n相对于使用列表实现的更简单模型，它们都已被证明是正确的。\n与此同时，映射与集合也具有可预测的性能。\n\n某些类型还包含了一些尚未完全验证的附加操作。\n这些操作依然很有用，而且并非所有程序都需要完全验证。\n例如 HashMap.partition 与 TreeMap.filterMap。\n\n\n\n\n\n\n\n","context":"Lean 中文参考手册\u0009基本类型\u0009映射与集合","header":"20.19.1. 库设计","id":"/Basic-Types/Maps-and-Sets/#Lean-__________________--Basic-Types--Maps-and-Sets--Library-Design"},"/Basic-Types/Strings/#Lean-__________________--Basic-Types--Strings--API-Reference--Raw-Substrings--Properties":{"contents":"检查子字符串是否为空。如果子字符串的开始位置和结束位置相同，则子字符串为空。\n\n字符串的 UTF-8 编码使用的字节数。\n\n","context":"Lean 中文参考手册\u0009基本类型\u0009字符串\u0009API 参考\u0009原始子字符串","header":"20.8.4.12.1. 属性","id":"/Basic-Types/Strings/#Lean-__________________--Basic-Types--Strings--API-Reference--Raw-Substrings--Properties"},"/Run-Time-Code/Boxing/#boxing":{"contents":"Lean 值在运行时可以用两种方式表示：* 装箱值可能是指向堆中值的指针，也可能需要通过移位和掩码才能取得。* 非装箱值可以直接取得。\n\n装箱值要么是指向对象的指针，此时最低位为 0；要么是立即值，此时最低位为 1，将其表示右移一位即可得到该值。\n\n采用非装箱表示的类型（例如 UInt8 和枚举归纳类型），在编译器能够确定值具有相应类型的上下文中，会表示为对应的 C 类型。\n在某些上下文中（例如 Array 这样的泛型容器类型），原本采用非装箱表示的值必须先装箱才能存储。\n换言之，由于枚举归纳类型 Bool 采用非装箱表示，调用 Bool.not 时传入和返回的都是非装箱的 uint8_t 值；但 Array Bool 中的各个 Bool 值则是装箱的。\n归纳类型构造器中类型为 Bool 的字段采用非装箱表示，而多态字段实例化为 Bool 后，其中存储的 Bool 则采用装箱表示。\n\n","context":"Lean 中文参考手册\u0009运行时代码","header":"12.1. 装箱","id":"/Run-Time-Code/Boxing/#boxing"},"/releases/v4.26.0/#The-Lean-Language-Reference--Release-Notes--Lean-4___26___0-_LPAR_2025-12-13_RPAR_--Highlights":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Lean 中文参考手册\u0009发行说明\u0009Lean 4.26.0 (2025-12-13)","header":"亮点","id":"/releases/v4.26.0/#The-Lean-Language-Reference--Release-Notes--Lean-4___26___0-_LPAR_2025-12-13_RPAR_--Highlights"},"/releases/v4.30.0/#The-Lean-Language-Reference--Release-Notes--Lean-4___30___0-_LPAR_2026-05-26_RPAR_--Highlights--Library-Highlights--HTTP-Library":{"contents":"#12126、#12127、#12128 和 #12144 介绍了核心 HTTP 数据类型：Request、Response、Status、Version、Method、Headers、URI 和流式 Body。这是 Lean 标准 HTTP 库的基础。\n\n","context":"Lean 中文参考手册\u0009发行说明\u0009Lean4.30.0 (2026-05-26)\u0009亮点\u0009库亮点","header":"HTTP 库","id":"/releases/v4.30.0/#The-Lean-Language-Reference--Release-Notes--Lean-4___30___0-_LPAR_2026-05-26_RPAR_--Highlights--Library-Highlights--HTTP-Library"}});